@startuml

class Customer {
  + name : string
  + phone_number : string
}

class Table {
  + number_of_seats : int
  + is_smoking : boolean
}

class Reservation {
  + day : date
  + time : time
  + number_of_people : int
}

class Waiter {
  + name : string
  + years_of_service : int
}

class Bill {
  + total_amount : double
}

class Dish {
  + name : string
  + unit_price : double
}

class BillLine {
  + quantity : int
}

Customer "1" -- "0..*" Reservation : makes
Reservation "0..*" -- "1..*" Table : assigns
Waiter "1" -- "*" Customer : serves
Customer "1" -- "0..*" Bill : pays
Bill "1" *-- "1..*" BillLine : contains
BillLine "*" -- "1" Dish : includes

@enduml

